import{_ as t}from"./chunks/qr_ob1_debug.BFcqNe1b.js";import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,o as n,c as i,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"G7, ONE+","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/g7.md","filePath":"troubleshoot/g7.md"}'),s={name:"troubleshoot/g7.md"};function l(h,e,c,d,g,p){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="g7-one-troubleshooting" tabindex="-1">G7, ONE+ troubleshooting <a class="header-anchor" href="#g7-one-troubleshooting" aria-label="Permalink to &quot;G7, ONE+ troubleshooting&quot;">​</a></h1><p>See <a href="./../install/g7.html">how to set up G7/ONE+</a> first if you haven&#39;t already. Many of the underlying causes below are the same as for <a href="./g6.html">G6/ONE</a> — signal strength and battery are covered there and linked from here rather than repeated.</p><h2 id="step-by-step-troubleshooting" tabindex="-1">Step-by-step troubleshooting <a class="header-anchor" href="#step-by-step-troubleshooting" aria-label="Permalink to &quot;Step-by-step troubleshooting&quot;">​</a></h2><p>If xDrip is set to collect directly from a G7/ONE+ but isn&#39;t receiving data, work through these in order:</p><ol><li>Disable <a href="./../use/misc.html#engineering-mode">engineering mode</a>.</li><li>Uninstall the Dexcom app, or any other app connecting directly to the sensor.</li><li>Check the sensor itself — can you see the filament protruding from the top? If so, photograph it for Dexcom: even once connected, the sensor won&#39;t give useful readings since the filament was never actually inserted under your skin, and you&#39;ll need a new one.</li><li><strong>&quot;Missing QR Code&quot; on the Dex Status page</strong> — use Settings → Auto Config to scan the QR code from the <a href="./../install/g7.html#setup-xdrip">setup guide</a>, not any code printed on the sensor itself, then tap <strong>Restart Collector</strong> on the Classic Status page.</li><li><strong>&quot;Mismatch - wait&quot; on the Dex Status page</strong> — you likely entered the pairing code wrong, or have old used sensors nearby. Move any previously used sensors more than 10 metres away, double-check the pairing code against the one printed on the applicator, then tap <strong>Restart Collector</strong>.</li><li><strong>Verify connectivity</strong> — if there&#39;s none, use a <a href="./g6.html#how-strong-is-the-transmitter-signal">Bluetooth scanner</a> to check whether the transmitter is visible at all, after moving old devices away. If it&#39;s still not visible, hold the applicator&#39;s magnet near the sensor for a few seconds — this can trigger it to activate — then check the scanner again and tap <strong>Restart Collector</strong>.</li><li><strong>&quot;Deep Sleeping Errors&quot;, &quot;Checking Auth Errors&quot;, &quot;Scanning Errors&quot; or &quot;Initializing Errors&quot; on the Dex Status page</strong>: <ol><li>Note down the current 4-digit transmitter ID from Settings.</li><li>Change its last digit to something else.</li><li>Disable collection in xDrip, and temporarily disable any pump, receiver, or watch connecting directly to the sensor.</li><li>Wait 15 minutes for G7 to enter <a href="#g7-rapid-reconnect-mode">rapid reconnect mode</a>.</li><li>Delete any Bluetooth devices named <code>DXCM*</code>, <code>DX01*</code>, <code>DX02*</code> or <code>DX04*</code> from Android&#39;s connected/previously-connected device list.</li><li>Re-enable the xDrip Dex collector (select Dex as the hardware data source) and restore the correct transmitter ID from your note.</li><li>Go to the Dex Status page, wait up to a minute for a pairing request, and approve it — if none appears, restart the phone.</li><li>Once connected with 3 consecutive readings, you can re-enable your pump, receiver, or watch.</li></ol></li><li><strong>&quot;Sensor Failed 7&quot; on the Dex Status page</strong> — avoid lying on the sensor and relax the limb it&#39;s on, stay hydrated, and give it up to 3 hours for readings to return. If readings do come but keep randomly dropping, see <a href="./g6.html#intermittent-connectivity">Intermittent connectivity</a>.</li></ol><h2 id="g7-rapid-reconnect-mode" tabindex="-1">G7 rapid reconnect mode <a class="header-anchor" href="#g7-rapid-reconnect-mode" aria-label="Permalink to &quot;G7 rapid reconnect mode&quot;">​</a></h2><p>Under normal conditions a G7/ONE+ transmits once every 5 minutes, with a two-way acknowledgment handshake each time. If it misses three acknowledgments in a row (15 minutes with no successful handshake), it switches to rapid reconnect mode: it repeats each reading up to 4 extra times, once per minute, so a reconnecting app doesn&#39;t have to wait a full 5-minute cycle to catch it. This continues for up to 12 hours, or until the app reconnects — whichever comes first.</p><p>As soon as a handshake succeeds, the extra transmissions stop. xDrip reads the timestamp on the reading it gets (which still corresponds to the underlying 5-minute schedule), so it re-synchronises correctly to the normal cadence even if it happened to catch one of the extra once-a-minute transmissions rather than the &quot;real&quot; one.</p><h2 id="ob1-debugging-logs" tabindex="-1">OB1 debugging logs <a class="header-anchor" href="#ob1-debugging-logs" aria-label="Permalink to &quot;OB1 debugging logs&quot;">​</a></h2><p>This applies to G6, ONE, G7 and ONE+ alike: they all use the same OB1 collector, which stores very little log detail by default. If a developer asks you for detailed logs while troubleshooting a connection issue, enable full OB1 logging first.</p><p>The easiest way is to scan this QR code with Settings, <a href="./../use/copysettings.html#auto-configure">Auto configure</a> and approve the import prompt. It only sets one preference, Extra tags for logging.</p><p>QR Code - Click image to expand</p><p><a href="./images/qr_ob1_debug.png"><img src="'+t+'" style="zoom:50%;"></a></p><p>You can also enter the tags by hand:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../use/lesscommon.html#extra-logging-settings">Extra Logging Settings</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Extra tags for logging</p><p> Ob1G5CollectionService:v,Ob1G5StateMachine:v</p></div><p>Then:</p><ul><li>Wait for the problem to actually happen before uploading. Enabling logging alone captures nothing useful yet.</li><li>Open the <a href="./../use/3dotsmenu.html#events-log">Events Log</a> from the 3 dots menu, tap Upload Logs, and add a note identifying the device so it can be matched up when you report it.</li><li>Disable it afterwards: clear the Extra tags for logging field and confirm. Otherwise it keeps generating a lot of extra log volume.</li></ul><h2 id="shared-with-g6one" tabindex="-1">Shared with G6/ONE <a class="header-anchor" href="#shared-with-g6one" aria-label="Permalink to &quot;Shared with G6/ONE&quot;">​</a></h2><p>These apply to G7/ONE+ transmitters too — see the <a href="./g6.html">G6, ONE troubleshooting</a> page for the full detail:</p><ul><li><a href="./g6.html#how-strong-is-the-transmitter-signal">How strong is the transmitter signal?</a></li><li><a href="./g6.html#how-good-is-the-battery">How good is the battery?</a></li><li><a href="./g6.html#transmitter-queue-stuck">Transmitter queue stuck</a></li></ul>',21)])])}const y=a(s,[["render",l]]);export{b as __pageData,y as default};
